mapper.select:
SELECT expert.*, expert_apply.BU_ID,expert_apply.BU_CODE,expert_apply.BU_NAME
FROM scc_npm_sou_expert expert
LEFT JOIN scc_npm_sou_expert_apply expert_apply on expert.EXPERT_APPLY_ID = expert_apply.EXPERT_APPLY_ID
WHERE
    1 = 1

    AND expert_apply.EXPERT_APPLY_NO like concat('%', concat(#{expertApplyNo}, '%'))


    AND expert_apply.APPLY_TIME >= #{applyTimeFrom}


    AND expert_apply.APPLY_TIME <= #{applyTimeTo}


    AND (
        expert_apply.APPLY_BY LIKE concat('%', concat(#{applyBy}, '%'))
        OR
        expert_apply.APPLY_BY_NICKNAME LIKE concat('%', concat(#{applyBy}, '%'))
    )


    AND expert_apply.APPLY_STATUS = #{applyStatus}


    AND expert.HAS_QUITE = #{hasQuite}
